class CqrsClientServiceStub(betterproto.ServiceStub):
    async def connect(
        self,
        client_message_iterator: Union[
            AsyncIterable[ClientMessage], Iterable[ClientMessage]
        ],
        *,
        timeout: Optional[float] = None,
        deadline: Optional["Deadline"] = None,
        metadata: Optional["MetadataLike"] = None
    ) -> AsyncIterator[ServerMessage]:
        async for response in self._stream_stream(
            "/CqrsClientService/Connect",
            client_message_iterator,
            ClientMessage,
            ServerMessage,
            timeout=timeout,
            deadline=deadline,
            metadata=metadata,
        ):
            yield response


class CqrsClientServiceBase(ServiceBase):

    async def connect(
        self, client_message_iterator: AsyncIterator[ClientMessage]
    ) -> AsyncIterator[ServerMessage]:
        raise grpclib.GRPCError(grpclib.const.Status.UNIMPLEMENTED)
        yield ServerMessage()

    async def __rpc_connect(
        self, stream: "grpclib.server.Stream[ClientMessage, ServerMessage]"
    ) -> None:
        request = stream.__aiter__()
        await self._call_rpc_handler_server_stream(
            self.connect,
            stream,
            request,
        )

    def __mapping__(self) -> Dict[str, grpclib.const.Handler]:
        return {
            "/CqrsClientService/Connect": grpclib.const.Handler(
                self.__rpc_connect,
                grpclib.const.Cardinality.STREAM_STREAM,
                ClientMessage,
                ServerMessage,
            ),
        }
